pair A, B;
pair[] C;

A = (0,0);
B = 5*dir(40);
C[1] = (2*B.x - 5,0);
C[2] = (5,0);

draw(A--B--C[2]--cycle);
draw(B--C[1]);

label("$A$", A, SW);
label("$B$", B, N);
label("$C_1$", C[1], S);
label("$C_2$", C[2], SE);
label("$13$", (A + B)/2, NW);
label("$10$", (B + C[2])/2, NE);
label("$10$", (B + C[1])/2, NW);
label("$40^\circ$", (1,0.4));
